#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8

repo_root="$(cd "$(dirname "$0")/../.." && pwd)"
hermes_home="${HERMES_HOME:-$HOME/.hermes}"
hermes_config="$hermes_home/config.yaml"
hermes_python="$hermes_home/hermes-agent/venv/bin/python"
nico_agent="${NICO_AGENT_INSTALL_DIR:-$HOME/.local/bin}/nico-agent"
nico_config="${NICO_AGENT_CONFIG_DIR:-${XDG_CONFIG_HOME:-$HOME/.config}/nico-agent}/config.json"
job_name="nico-agent-scheduler"
# Nothing here goes to a .env; keep `ask` from offering defaults out of one.
ENV_FILE=/dev/null

# The toolsets that would let Hermes run a command, touch files or reach out on its own.
required_denied=(terminal file code_execution browser web computer_use delegation cronjob)
# What Hermes keeps: nico-agent's three tools, and what the routine's memory needs.
allowed_tools="board, advance and answer, plus memory, session_search and the skills tools"

cron_prompt='Run one tick of the nico-agent Scheduler routine from the nico-agent skill. Your final response is the message delivered to the user'"'"'s chat. Report a failed row once, and again only when its reason changes. Keep the Present / Postponed / Away state, the open proposal and the Held Specs, failed rows and Implementer questions already reported in memory: the chat session that receives the user'"'"'s replies reads the same memory. If nothing changed that the user needs to hear, reply with exactly [SILENT].'

banner "Hermes as the nico-agent Scheduler"

stage "Install nico-agent from this checkout"
say "Hermes runs the installed nico-agent, which needs \`mcp\` and \`--skill\`."
if "$nico_agent" --skill >/dev/null 2>&1; then
  note "installed: $("$nico_agent" --version) at $nico_agent, with --skill"
else
  warn "$nico_agent is missing or predates \`--skill\`"
fi
if confirm "Build and install nico-agent from $repo_root?"; then
  "$repo_root/scripts/install.sh"
fi
"$nico_agent" --skill >/dev/null 2>&1 || { warn "the installed nico-agent still has no --skill; stopping"; exit 1; }

stage "nico-agent: Scheduler defaults and room"
say "\`advance\` dispatches every issue with one Harness, model and Effort from"
say "$nico_config, so Hermes never chooses them."
[[ -f "$nico_config" ]] || { warn "no $nico_config: add a Repo with \`nico-agent repo add\` first"; exit 1; }
current=$(jq -c '.scheduler // empty' "$nico_config")
note "current: ${current:-unset}"
if [[ -z "$current" ]] || confirm "Change them?"; then
  step "Pick from the Harnesses below."
  "$nico_agent" harness list || true
  ask SCHED_HARNESS "Harness:"
  ask SCHED_MODEL "Model:"
  ask SCHED_EFFORT "Effort:"
  cp "$nico_config" "$nico_config.bak-before-scheduler"
  tmp=$(mktemp)
  jq --arg h "$SCHED_HARNESS" --arg m "$SCHED_MODEL" --arg e "$SCHED_EFFORT" \
    '.scheduler = {harness: $h, model: $m, effort: $e}' "$nico_config" > "$tmp"
  mv "$tmp" "$nico_config"
  printf '  %s✓ wrote%s scheduler defaults → %s (backup: .bak-before-scheduler)\n' "$GREEN" "$RESET" "$nico_config"
fi
say ""
say "Room per Repo right now:"
"$nico_agent" --json | jq -r '.rooms[] | "    \(.repo): room \(.room), \(.candidates | length) candidate Specs"'
warn "While you are Away, Hermes starts candidates in any Repo with room."
note "Keep it off a Repo with \`nico-agent repo rm\`, or lower its maxRunningSpecs in $nico_config."
pause "Press Enter once the Repos and their room are what Hermes may act on."

stage "Hermes: register nico-agent mcp as the only extra tools"
[[ -f "$hermes_config" ]] || { warn "no $hermes_config: run \`hermes setup\` first"; exit 1; }
missing=()
for t in "${required_denied[@]}"; do
  "$hermes_python" -c "import yaml,sys; sys.exit(0 if sys.argv[2] in ((yaml.safe_load(open(sys.argv[1])).get('agent') or {}).get('disabled_toolsets') or []) else 1)" "$hermes_config" "$t" || missing+=("$t")
done
if (( ${#missing[@]} )); then
  warn "agent.disabled_toolsets in $hermes_config does not deny: ${missing[*]}"
  note "Add them there before Hermes acts as the Scheduler."
  SKIPPED+=("deny toolsets ${missing[*]} in agent.disabled_toolsets")
else
  note "agent.disabled_toolsets denies ${required_denied[*]}"
fi
included=$("$hermes_python" -c "import yaml,sys; c=yaml.safe_load(open(sys.argv[1])) or {}; s=(c.get('mcp_servers') or {}).get('nico-agent'); print(' '.join((s.get('tools') or {}).get('include') or []) if s else '')" "$hermes_config")
if [[ -n "$included" && " $included " != *" answer "* ]]; then
  warn "mcp_servers.nico-agent in $hermes_config includes only: $included"
  note "Add answer to its tools.include, so Hermes can relay your answers to Implementers waiting on you."
  pause "Press Enter once it reads include: [board, advance, answer]."
elif [[ -n "$included" ]]; then
  note "mcp_servers.nico-agent includes: $included"
elif grep -qE '^mcp_servers:' "$hermes_config"; then
  warn "$hermes_config already has mcp_servers; add this entry under it by hand:"
  note "  nico-agent: {command: $nico_agent, args: [mcp], env: {PATH: \"\${userHome}/.local/share/mise/shims:\${PATH}\"}, tools: {include: [board, advance, answer], resources: false, prompts: false}}"
  pause "Press Enter once the entry is in place."
elif confirm "Append the nico-agent MCP server to $hermes_config?"; then
  cp "$hermes_config" "$hermes_config.bak-before-nico-agent-mcp"
  cat >> "$hermes_config" <<EOF

# nico-agent Scheduler (nico-agent scripts/hermes/setup.sh): only its three tools.
mcp_servers:
  nico-agent:
    command: $nico_agent
    args: [mcp]
    env:
      PATH: "\${userHome}/.local/share/mise/shims:\${PATH}"
    tools:
      include: [board, advance, answer]
      resources: false
      prompts: false
EOF
  "$hermes_python" -c "import yaml,sys; yaml.safe_load(open(sys.argv[1]))" "$hermes_config"
  printf '  %s✓ wrote%s mcp_servers.nico-agent → %s (backup: .bak-before-nico-agent-mcp)\n' "$GREEN" "$RESET" "$hermes_config"
fi
hermes mcp test nico-agent || warn "hermes mcp test failed; fix the entry and re-run this wizard"
pause

stage "Hermes: install the Scheduler skill"
mkdir -p "$hermes_home/skills/nico-agent"
"$nico_agent" --skill > "$hermes_home/skills/nico-agent/SKILL.md"
printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$hermes_home/skills/nico-agent/SKILL.md"
note "Hermes keeps its skills toolset, so it could edit this copy; re-run this stage to restore it."
pause

stage "Hermes: install the monitor script"
say "Each tick it runs \`nico-agent advance\` and prints the Board's room and Held Specs;"
say "Hermes wakes its agent only when that output changes."
mkdir -p "$hermes_home/scripts"
install -m 755 "$repo_root/scripts/hermes/nico-agent-monitor.sh" "$hermes_home/scripts/nico-agent-monitor.sh"
printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$hermes_home/scripts/nico-agent-monitor.sh"
pause

stage "Hermes: restart the gateway and check its tools"
if confirm "Restart the Hermes gateway so it loads the MCP server and skill?"; then
  hermes gateway restart
fi
step "In your Hermes chat, send: List every tool you can call, by exact name."
say "Expect $allowed_tools."
say "Nothing that runs commands, reads or writes files, or browses."
if ! confirm "Did Hermes list only those?"; then
  SKIPPED+=("Hermes still has tools beyond $allowed_tools")
fi

stage "Hermes: the 10-minute cron job"
jobs=$(hermes cron list 2>/dev/null || true)
if grep -q "$job_name" <<<"$jobs"; then
  note "a job named $job_name already exists:"
  grep -A3 "$job_name" <<<"$jobs" || true
else
  ask DELIVER "Deliver to (telegram, or platform:chat_id) [telegram]:"
  DELIVER="${DELIVER:-telegram}"
  if confirm "Create the $job_name job, every 10m, delivering to $DELIVER?"; then
    hermes cron create 10m "$cron_prompt" \
      --name "$job_name" \
      --skill nico-agent \
      --monitor-script nico-agent-monitor.sh \
      --deliver "$DELIVER"
  else
    SKIPPED+=("create the $job_name cron job")
  fi
fi
hermes cron status || true
pause

stage "Run it on a small real Spec"
say "Watch one Spec through, answering in your Hermes chat."
step "In a Repo with room 2, make two small Specs: GitHub issues with 2 sub-issues each,"
step "every sub-issue Ready (labelled ready-for-agent), or Linear parents alike."
note "You answer one by name; Hermes picks the other while you are Away."
step "Start a tick now: \`hermes cron run <id>\` (the id is in \`hermes cron list\`)."
note "A tick in the same 10 minutes as the last one, with nothing changed, stays silent."
confirm "A proposal arrived, recommended Spec first, each with a reason?" || SKIPPED+=("observe a proposal")
step "Reply \"later\". No proposal for that Repo should come within the hour; one comes after."
confirm "\"later\" postponed it for an hour, then it proposed again?" || SKIPPED+=("observe a \"later\"")
step "Reply with the Spec's name; Hermes starts it, and later ticks keep it moving."
confirm "It started the Spec you named?" || SKIPPED+=("observe a proposal answered")
step "Leave the proposal for the other Spec unanswered 30 minutes: Hermes is Away and starts its pick."
confirm "It started its own pick and told you why?" || SKIPPED+=("observe an Away pick")
note "Record what you saw on issue #45."

finish
